using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
namespace CampaignDemo {
 public sealed class LocalMapSettings:MonoBehaviour {
  Font font;BattleWorld world;Material material;readonly Dictionary<Button,string> commandButtons=new Dictionary<Button,string>();
  readonly Dictionary<FortificationLineWorks.Project,LineRenderer> lines=new Dictionary<FortificationLineWorks.Project,LineRenderer>();
  public static bool CapturesPointer(BattleWorld world){return false;}
  GameObject controls;CampaignHUD hud;RectTransform controlsRect;float previousWidth=-1;Text timeCaption;BattleTimeControl clock;readonly List<Button> timeButtons=new List<Button>();
  Text Label(Transform parent,string value,int fontSize){var go=new GameObject("提示",typeof(RectTransform),typeof(Text));go.transform.SetParent(parent,false);var t=go.GetComponent<Text>();t.font=font;t.fontSize=fontSize;t.lineSpacing=1.15f;t.color=StaffMapStyle.Ink;t.alignment=TextAnchor.MiddleCenter;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Truncate;t.raycastTarget=false;t.text=value;return t;}
  void Start(){world=GetComponent<BattleWorld>();font=Font.CreateDynamicFontFromOSFont(new[]{"Microsoft YaHei","Arial"},16);material=new Material(Shader.Find("Sprites/Default"));hud=FindObjectOfType<CampaignHUD>();if(hud==null)return;
   controls=new GameObject("离线战术指令",typeof(RectTransform),typeof(VerticalLayoutGroup),typeof(ContentSizeFitter));controls.transform.SetParent(hud.transform,false);controlsRect=controls.GetComponent<RectTransform>();controlsRect.anchorMin=controlsRect.anchorMax=controlsRect.pivot=new Vector2(.5f,1);
   var layout=controls.GetComponent<VerticalLayoutGroup>();layout.spacing=5;layout.padding=new RectOffset(4,4,3,3);layout.childControlWidth=layout.childControlHeight=true;layout.childForceExpandWidth=true;layout.childForceExpandHeight=false;layout.childAlignment=TextAnchor.UpperCenter;controls.GetComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;
   if(LocalPrototypeOrders.EnabledFor(this)){
    var commands=new GameObject("路线与协同设置",typeof(RectTransform),typeof(HorizontalLayoutGroup),typeof(LayoutElement));commands.transform.SetParent(controls.transform,false);commands.GetComponent<LayoutElement>().preferredHeight=28;var commandLayout=commands.GetComponent<HorizontalLayoutGroup>();commandLayout.spacing=5;commandLayout.childControlHeight=commandLayout.childControlWidth=true;
    CommandButton(commands.transform,"自动寻路 Q",()=>world.setup.modes.SelectMarch(MouseCommandMode.RoadMarch));CommandButton(commands.transform,"直线行军 E",()=>world.setup.modes.SelectMarch(MouseCommandMode.FreeMarch));CommandButton(commands.transform,"巡逻运输 R",()=>world.GetComponent<LocalPrototypeOrders>().ToggleDraft(LocalPrototypeOrders.DraftKind.Patrol));CommandButton(commands.transform,"轮换 K",()=>world.GetComponent<LocalCoordinatedOrders>().TogglePicking(LocalCoordinatedOrders.PickMode.Rotation));CommandButton(commands.transform,"联防 H",()=>world.GetComponent<LocalCoordinatedOrders>().TogglePicking(LocalCoordinatedOrders.PickMode.Defense));
   }
   Label(controls.transform,"1 对半分兵    2 佯攻分队    3 渗透分队    Z/X/C 行军姿态",15);
   Label(controls.transform,LocalPrototypeOrders.EnabledFor(this)?"R 巡逻    K 轮换    H 联防    T 停止    F 炮击    WASD 平移    滚轮缩放":"T 停止    F 炮击    WASD 平移    滚轮缩放",17);
   Label(controls.transform,LocalPrototypeOrders.EnabledFor(this)?"Q / E 切换行军，点击目的地立即出发；R 设置巡逻运输，再按 R 执行；Esc 取消设置。":"先选部队，再点击目的地 / 敌军 / 运兵车",14);
   clock=controls.AddComponent<BattleTimeControl>();
   var row=new GameObject("时间加速",typeof(RectTransform),typeof(HorizontalLayoutGroup),typeof(LayoutElement));row.transform.SetParent(controls.transform,false);row.GetComponent<LayoutElement>().minHeight=30;row.GetComponent<LayoutElement>().preferredHeight=30;var horizontal=row.GetComponent<HorizontalLayoutGroup>();horizontal.spacing=8;horizontal.childControlWidth=horizontal.childControlHeight=true;horizontal.childForceExpandWidth=false;horizontal.childForceExpandHeight=true;horizontal.childAlignment=TextAnchor.MiddleCenter;
   var caption=Label(row.transform,"时间：1×",16);timeCaption=caption;caption.gameObject.AddComponent<LayoutElement>().preferredWidth=86;
   foreach(int rate in new[]{1,2,4}){int multiplier=rate;var text=Label(row.transform,rate+"×",16);text.name="时间倍率 "+rate;text.raycastTarget=true;text.gameObject.AddComponent<LayoutElement>().preferredWidth=40;var button=text.gameObject.AddComponent<Button>();timeButtons.Add(button);button.targetGraphic=text;button.transition=Selectable.Transition.None;button.onClick.AddListener(()=>{clock.SetMultiplier(multiplier);caption.text="时间："+multiplier+"×";});}
   ArrangeControls();
  }
  void CommandButton(Transform parent,string title,UnityEngine.Events.UnityAction action){var go=new GameObject(title,typeof(RectTransform),typeof(Image),typeof(Button),typeof(LayoutElement));go.transform.SetParent(parent,false);go.GetComponent<LayoutElement>().preferredHeight=28;go.GetComponent<LayoutElement>().flexibleWidth=1;go.GetComponent<Image>().color=StaffMapStyle.Inset;var text=Label(go.transform,title,13);text.rectTransform.anchorMin=Vector2.zero;text.rectTransform.anchorMax=Vector2.one;text.rectTransform.offsetMin=text.rectTransform.offsetMax=Vector2.zero;var button=go.GetComponent<Button>();button.navigation=new Navigation{mode=Navigation.Mode.None};button.onClick.AddListener(action);commandButtons[button]=title;}
  void ArrangeControls(){if(controlsRect==null||hud==null)return;var canvas=hud.GetComponentInParent<Canvas>();var canvasRect=canvas==null?null:canvas.GetComponent<RectTransform>();float width=canvasRect==null?Screen.width:canvasRect.rect.width;float right=width>=600?hud.rightPanelWidth+12:0;float available=Mathf.Max(100,width-right-24);float desired=Mathf.Min(680,available);if(Mathf.Abs(previousWidth-desired)>.1f){controlsRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal,desired);previousWidth=desired;LayoutRebuilder.ForceRebuildLayoutImmediate(controlsRect);}controlsRect.anchoredPosition=new Vector2(-right*.5f,LocalPvpSession.Active==null?-10:-120);}
  void LateUpdate(){foreach(var pair in commandButtons){var orders=world==null?null:world.GetComponent<LocalPrototypeOrders>();var coordinated=world==null?null:world.GetComponent<LocalCoordinatedOrders>();bool active=orders!=null&&orders.Drafting&&(pair.Value=="自动寻路 Q"&&orders.CurrentDraft==LocalPrototypeOrders.DraftKind.Road||pair.Value=="直线行军 E"&&orders.CurrentDraft==LocalPrototypeOrders.DraftKind.Straight||pair.Value=="巡逻运输 R"&&orders.CurrentDraft==LocalPrototypeOrders.DraftKind.Patrol)||coordinated!=null&&(pair.Value=="轮换 K"&&coordinated.Picking==LocalCoordinatedOrders.PickMode.Rotation||pair.Value=="联防 H"&&coordinated.Picking==LocalCoordinatedOrders.PickMode.Defense);bool marchSelected=world!=null&&world.setup!=null&&(pair.Value=="自动寻路 Q"&&world.setup.modes.CurrentMode==MouseCommandMode.RoadMarch||pair.Value=="直线行军 E"&&world.setup.modes.CurrentMode==MouseCommandMode.FreeMarch);pair.Key.GetComponentInChildren<Text>().text=active?"完成 "+pair.Value:pair.Value;pair.Key.image.color=active||marchSelected?new Color(.7f,.6f,.35f):StaffMapStyle.Inset;}ArrangeControls();if(clock!=null&&timeCaption!=null)timeCaption.text="时间："+clock.Multiplier.ToString("0")+"×";foreach(var button in timeButtons)button.interactable=LocalPvpSession.Active==null||LocalPvpSession.Active.IsHost;if(world==null||!world.Initialized)return;var current=new HashSet<FortificationLineWorks.Project>(world.campaign.lineWorks.ActiveProjects);foreach(var p in new List<FortificationLineWorks.Project>(lines.Keys))if(!current.Contains(p)){Destroy(lines[p].gameObject);lines.Remove(p);}foreach(var p in current){if(p.fort!=null)continue;if(!lines.TryGetValue(p,out var line)){var g=new GameObject("施工中的防线 · Shift＋左键协助");line=g.AddComponent<LineRenderer>();line.sharedMaterial=material;line.sortingOrder=26;line.positionCount=p.points.Length;line.SetPositions(p.points);line.startWidth=line.endWidth=LocalPrototypeOrders.EnabledFor(this)?.12f:.07f;lines.Add(p,line);}line.startColor=line.endColor=Color.Lerp(StaffMapStyle.Rule,StaffMapStyle.Blue,world.campaign.lineWorks.Progress(p));}}
  void OnDestroy(){if(controls!=null)Destroy(controls);foreach(var line in lines.Values)if(line!=null)Destroy(line.gameObject);if(material!=null)Destroy(material);if(font!=null)Destroy(font);}
 }
}
